        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90020020-0000-4000-8000-000000000001', 'The mean of five numbers is 30. If one number is excluded, their mean becomes 28. The excluded number is:', '{"A":"36","B":"38","C":"40","D":"42"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Statistics', 1, NULL, NULL, NULL, 'Sum of 5 numbers = 5 * 30 = 150. Sum of remaining 4 numbers = 4 * 28 = 112. Excluded number = 150 - 112 = 38.', 'MEDIUM', true),
        ('90020020-0000-4000-8000-000000000002', 'In a frequency distribution, the class mark of the class 130 - 150 is:', '{"A":"135","B":"140","C":"145","D":"20"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Statistics', 1, NULL, NULL, NULL, 'Class mark = (Lower limit + Upper limit) / 2 = (130 + 150) / 2 = 140.', 'MEDIUM', true),
        ('90020020-0000-4000-8000-000000000003', 'Assertion (A): The polynomial p(x) = 3x² + 5x - 2 is a quadratic polynomial.
